create extension if not exists pgcrypto;
create type vehicle_status as enum ('draft','available','reserved','sold');
create type lead_status as enum ('new','contacted','closed');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, role text not null default 'admin' check(role in('admin')), created_at timestamptz default now());
create table public.vehicles (id uuid primary key default gen_random_uuid(), slug text unique not null, manufacturer text not null, model text not null, generation text, year int not null check(year between 1950 and 2100), price numeric(12,2) not null check(price>=0), mileage int not null check(mileage>=0), fuel text not null, transmission text not null, engine text, power_kw int, body_type text, color text, vin text, technical_inspection date, description text not null default '', preparation text not null default '', status vehicle_status not null default 'draft', published boolean not null default false, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.vehicle_images (id uuid primary key default gen_random_uuid(), vehicle_id uuid not null references public.vehicles(id) on delete cascade, storage_path text not null, sort_order int not null default 0, is_cover boolean not null default false, created_at timestamptz default now());
create table public.vehicle_features (id uuid primary key default gen_random_uuid(), vehicle_id uuid not null references public.vehicles(id) on delete cascade, feature text not null, sort_order int not null default 0);
create table public.leads (id uuid primary key default gen_random_uuid(), vehicle_id uuid not null references public.vehicles(id) on delete cascade, customer_name text not null, phone text not null, email text, message text not null, status lead_status not null default 'new', created_at timestamptz default now());
create table public.settings (key text primary key, value jsonb not null default '{}'::jsonb);
alter table public.profiles enable row level security; alter table public.vehicles enable row level security; alter table public.vehicle_images enable row level security; alter table public.vehicle_features enable row level security; alter table public.leads enable row level security; alter table public.settings enable row level security;
create policy "public read published vehicles" on public.vehicles for select using (published=true and status <> 'draft');
create policy "public read images for published vehicles" on public.vehicle_images for select using (exists(select 1 from public.vehicles v where v.id=vehicle_id and v.published=true));
create policy "public read features for published vehicles" on public.vehicle_features for select using (exists(select 1 from public.vehicles v where v.id=vehicle_id and v.published=true));
create policy "public create leads" on public.leads for insert with check (exists(select 1 from public.vehicles v where v.id=vehicle_id and v.published=true));
create policy "admins manage vehicles" on public.vehicles for all to authenticated using (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create policy "admins manage images" on public.vehicle_images for all to authenticated using (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create policy "admins manage features" on public.vehicle_features for all to authenticated using (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin')) with check (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create policy "admins read/update leads" on public.leads for select to authenticated using (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
create policy "admins update leads" on public.leads for update to authenticated using (exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('vehicle-images','vehicle-images',true,8388608,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
